/* From Uiverse.io by OnCloud125252 - Tags: simple, black, button, simple button, more info, read more */
/* Note that you only needs to edit the config to customize the button! */

.__UIV_SCOPE__ .plusButton {
  /* Config start */
  --plus_sideLength: 2.5rem;
  --plus_topRightTriangleSideLength: 0.9rem;
  /* Config end */
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  border: 1px solid white;
  width: var(--plus_sideLength);
  height: var(--plus_sideLength);
  background-color: #000000;
  overflow: hidden;
}

.__UIV_SCOPE__ .plusButton::before {
  position: absolute;
  content: "";
  top: 0;
  right: 0;
  width: 0;
  height: 0;
  border-width: 0 var(--plus_topRightTriangleSideLength) var(--plus_topRightTriangleSideLength) 0;
  border-style: solid;
  border-color: transparent white transparent transparent;
  transition-timing-function: ease-in-out;
  transition-duration: 0.2s;
}

.__UIV_SCOPE__ .plusButton:hover {
  cursor: pointer;
}

.__UIV_SCOPE__ .plusButton:hover::before {
  --plus_topRightTriangleSideLength: calc(var(--plus_sideLength) * 2);
}

.__UIV_SCOPE__ .plusButton:focus-visible::before {
  --plus_topRightTriangleSideLength: calc(var(--plus_sideLength) * 2);
}

.__UIV_SCOPE__ .plusButton>.plusIcon {
  fill: white;
  width: calc(var(--plus_sideLength) * 0.7);
  height: calc(var(--plus_sideLength) * 0.7);
  z-index: 1;
  transition-timing-function: ease-in-out;
  transition-duration: 0.2s;
}

.__UIV_SCOPE__ .plusButton:hover>.plusIcon {
  fill: black;
  transform: rotate(180deg);
}

.__UIV_SCOPE__ .plusButton:focus-visible>.plusIcon {
  fill: black;
  transform: rotate(180deg);
}
